										images.push({
											image: part.image,
											mimeType: part.mimeType,
											providerMetadata: part.providerMetadata,
										});
									}
									return ""; // No text for the image part
								}
							}
						})
						.join("\n"),
					role: "user",
				});
				break;
			}

			case "assistant": {
				let text = "";
				const toolCalls: Array<{
					id: string;
					type: "function";
					function: { name: string; arguments: string };
				}> = [];

				for (const part of content) {
					switch (part.type) {
						case "text": {
							text += part.text;
							break;
						}

						case "reasoning": {
							text += part.text;
							break;
						}

						case "tool-call": {
							text = JSON.stringify({
								name: part.toolName,
								parameters: part.args,
							});

							toolCalls.push({
								function: {
									arguments: JSON.stringify(part.args),
									name: part.toolName,
								},
								id: part.toolCallId,
								type: "function",
							});
							break;
						}
						default: {
							const exhaustiveCheck = part;
							throw new Error(`Unsupported part type: ${exhaustiveCheck.type}`);
						}
					}
				}

				messages.push({
					content: text,
					role: "assistant",
					tool_calls:
						toolCalls.length > 0
							? toolCalls.map(({ function: { name, arguments: args } }, index) => ({
									function: { arguments: args, name },
									id: `functions.${name}:${index}`,
									type: "function",
								}))
							: undefined,
				});

				break;
			}

			case "tool": {
				for (const [index, toolResponse] of content.entries()) {
					messages.push({
						content: JSON.stringify(toolResponse.result),
						name: toolResponse.toolName,
						tool_call_id: `functions.${toolResponse.toolName}:${index}`,
						role: "tool",
					});
