import { AIChatAgent } from "@cloudflare/ai-chat";
import { streamText, convertToCoreMessages, tool } from "ai";
import { createWorkersAI } from "workers-ai-provider";
import { z } from "zod";
import type { Env } from "./types";
import { D1_SCHEMA } from "./schema";

const MODEL_ID = "@cf/meta/llama-3.3-70b-instruct-fp8-fast" as const;

const SYSTEM_PROMPT = `あなたは Oura Ring データのアシスタントです。
ユーザーの質問に対して、D1データベース (SQLite) に対するSQLを生成・実行して回答します。

## 利用可能なデータ
Oura Ring から取得した健康データ（睡眠、活動、コンディション、心拍数）

## スキーマ
${D1_SCHEMA}

## ルール
- SELECT クエリのみ実行可能です。INSERT/UPDATE/DELETE は拒否してください。
- 日本語で回答してください。
- v_oura_daily_summary ビューが使える場合はそちらを優先してください。
- 大量データの取得は LIMIT を付けてください。
- 結果を簡潔にまとめて回答してください。
`;

function isSafeQuery(sql: string): boolean {
  const normalized = sql.trim().toUpperCase();
  return normalized.startsWith("SELECT") || normalized.startsWith("WITH");
}

export class DataAgent extends AIChatAgent<Env> {
  async onChatMessage(
    onFinish: Parameters<AIChatAgent<Env>["onChatMessage"]>[0],
    options?: Parameters<AIChatAgent<Env>["onChatMessage"]>[1]
  ) {
    const workersai = createWorkersAI({ binding: this.env.AI });

    const result = streamText({
      // @ts-expect-error -- model ID is valid at runtime but not in bundled types
      model: workersai(MODEL_ID),
      system: SYSTEM_PROMPT,
      messages: convertToCoreMessages(this.messages),
      abortSignal: options?.abortSignal,
      maxSteps: 5,
      tools: {
        queryD1: tool({
          description:
            "D1データベースに対してSELECTクエリを実行する。読み取り専用。",
          parameters: z.object({
            sql: z.string().describe("実行するSELECTクエリ"),
            params: z.array(z.string()).optional().describe("バインドパラメータ"),
          }),
          execute: async ({ sql, params }) => {
            if (!isSafeQuery(sql)) {
              return { success: false, error: "SELECT/WITH クエリのみ実行可能です。" };
            }
            try {
              const stmt = this.env.DB.prepare(sql);
              const bound = params?.length ? stmt.bind(...params) : stmt;
              const queryResult = await bound.all();

              return {
                success: true,
                rowCount: queryResult.results.length,
                results: queryResult.results.slice(0, 50),
              };
            } catch (error) {
              return {
                success: false,
                error: error instanceof Error ? error.message : String(error),
              };
            }
          },
        }),
        listTables: tool({
          description: "D1データベースの全テーブルとビューの一覧を取得する",
          parameters: z.object({}),
          execute: async () => {
            const queryResult = await this.env.DB.prepare(
              "SELECT name, type FROM sqlite_master WHERE type IN ('table', 'view') ORDER BY type, name"
            ).all();
            return queryResult.results;
          },
        }),
      },
    });

    return result.toDataStreamResponse();
  }
}

